import csv, json, os
from datetime import date

ROOT = os.path.dirname(__file__)
PATH = os.path.join(ROOT, 'E-large-home-appliances.csv')
FIELDS = ['category_code','department','subcategory','product_type','product_name','manufacturer','brand','model','manufacturer_part_number','gtin','description','specifications_json','image_url','product_url','release_date','release_date_precision','release_year','official_price','price_currency','price_type','price_market','price_source_url','product_source_url','source_attribution','collected_on','verification_status','notes']
DEPARTMENT = 'Large Home Appliances'
TODAY = date(2026, 10, 13).isoformat()
rows = []

def add(sub, typ, name, brand, model, url, specs, *, desc='', year='', released='', precision='', price='', currency='INR', market='India', ptype='current_listed', purl='', notes=''):
    rows.append({
        'category_code':'E','department':DEPARTMENT,'subcategory':sub,'product_type':typ,
        'product_name':name,'manufacturer':brand,'brand':brand,'model':model,
        'manufacturer_part_number':model,'gtin':'','description':desc,
        'specifications_json':json.dumps(specs, ensure_ascii=False, separators=(',',':')),
        'image_url':'','product_url':url,'release_date':released,'release_date_precision':precision,
        'release_year':str(year) if year else '', 'official_price':str(price) if price else '',
        'price_currency':currency if price else '', 'price_type':ptype if price else '',
        'price_market':market if price else '', 'price_source_url':purl or (url if price else ''),
        'product_source_url':url,'source_attribution':'Official manufacturer product page or announcement',
        'collected_on':TODAY,'verification_status':'official_manufacturer_source_verified',
        'notes':notes or ('Release year not independently stated on the cited product page; confirm before import.' if not year else '')
    })

