# Write rows with a stable schema and deterministic order; skip duplicate keys if rerun.
with open(PATH, 'w', newline='', encoding='utf-8-sig') as f:
    writer=csv.DictWriter(f, fieldnames=FIELDS, extrasaction='ignore')
    writer.writeheader()
    seen=set()
    for row in rows:
        key=(row['brand'].casefold(),row['model'].casefold())
        if key in seen:
            raise ValueError(f'duplicate model {key}')
        seen.add(key)
        writer.writerow(row)
print(f'Wrote {len(rows)} E records')
